-- Phase 5C attempt-safe voucher administration. UNAPPLIED; service role only.
BEGIN;
CREATE TABLE IF NOT EXISTS public.voucher_admin_sessions (telegram_user_id bigint PRIMARY KEY CHECK(telegram_user_id=6396446903),step text NOT NULL,voucher_type text,plan_code text,requested_quantity bigint,confirmation_key uuid,expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS public.voucher_batches (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),batch_reference text UNIQUE NOT NULL CHECK(batch_reference ~ '^VB-[A-F0-9]{12}$'),actor_user_id uuid NOT NULL REFERENCES public.app_users(id),voucher_type text NOT NULL,plan_code text NOT NULL,requested_quantity bigint NOT NULL CHECK(requested_quantity>0),generated_quantity bigint NOT NULL DEFAULT 0 CHECK(generated_quantity<=requested_quantity),delivered_quantity bigint NOT NULL DEFAULT 0 CHECK(delivered_quantity<=generated_quantity),finalized_quantity bigint NOT NULL DEFAULT 0 CHECK(finalized_quantity<=delivered_quantity),progress_cursor bigint NOT NULL DEFAULT 0,status text NOT NULL DEFAULT 'pending_delivery',confirmation_key uuid UNIQUE NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.voucher_batch_chunks (batch_id uuid NOT NULL REFERENCES public.voucher_batches(id),chunk_index bigint NOT NULL,expected_count integer NOT NULL CHECK(expected_count BETWEEN 1 AND 100),current_attempt_id uuid,status text NOT NULL DEFAULT 'pending',generated_count integer NOT NULL DEFAULT 0,delivered_count integer NOT NULL DEFAULT 0,finalized_count integer NOT NULL DEFAULT 0,PRIMARY KEY(batch_id,chunk_index));
CREATE TABLE IF NOT EXISTS public.voucher_batch_chunk_attempts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),batch_id uuid NOT NULL,chunk_index bigint NOT NULL,attempt_number integer NOT NULL,claim_token uuid NOT NULL,expected_count integer NOT NULL CHECK(expected_count BETWEEN 1 AND 100),stored_count integer NOT NULL DEFAULT 0,delivered_count integer NOT NULL DEFAULT 0,status text NOT NULL CHECK(status IN ('claimed','prepared','delivered','delivery_uncertain','finalized','cancelled')),lease_expires_at timestamptz NOT NULL,delivery_method text,telegram_message_id bigint,prepared_at timestamptz,delivered_at timestamptz,uncertain_at timestamptz,finalized_at timestamptz,cancelled_at timestamptz,last_safe_result_code text,UNIQUE(batch_id,chunk_index,attempt_number),FOREIGN KEY(batch_id,chunk_index) REFERENCES public.voucher_batch_chunks(batch_id,chunk_index));
ALTER TABLE public.subscription_vouchers ADD COLUMN IF NOT EXISTS batch_id uuid REFERENCES public.voucher_batches(id),ADD COLUMN IF NOT EXISTS chunk_index bigint,ADD COLUMN IF NOT EXISTS attempt_id uuid REFERENCES public.voucher_batch_chunk_attempts(id),ADD COLUMN IF NOT EXISTS item_index integer,ADD COLUMN IF NOT EXISTS voucher_reference text UNIQUE,ADD COLUMN IF NOT EXISTS delivery_pending boolean NOT NULL DEFAULT false;
DROP INDEX IF EXISTS public.subscription_voucher_chunk_item_idx; CREATE UNIQUE INDEX IF NOT EXISTS subscription_voucher_attempt_item_idx ON public.subscription_vouchers(attempt_id,item_index);
ALTER TABLE public.voucher_admin_sessions ENABLE ROW LEVEL SECURITY;ALTER TABLE public.voucher_batches ENABLE ROW LEVEL SECURITY;ALTER TABLE public.voucher_batch_chunks ENABLE ROW LEVEL SECURITY;ALTER TABLE public.voucher_batch_chunk_attempts ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.voucher_admin_sessions,public.voucher_batches,public.voucher_batch_chunks,public.voucher_batch_chunk_attempts FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.claim_voucher_admin_batch_chunk(p_batch_reference text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE b public.voucher_batches%ROWTYPE;c public.voucher_batch_chunks%ROWTYPE;a public.voucher_batch_chunk_attempts%ROWTYPE; BEGIN SELECT * INTO b FROM public.voucher_batches WHERE batch_reference=p_batch_reference FOR UPDATE; IF NOT FOUND OR b.status='cancelled' THEN RAISE EXCEPTION 'voucher unavailable'; END IF; IF b.finalized_quantity=b.requested_quantity THEN RETURN jsonb_build_object('done',true); END IF; INSERT INTO public.voucher_batch_chunks(batch_id,chunk_index,expected_count,status) VALUES(b.id,b.progress_cursor/100,least(100,b.requested_quantity-b.finalized_quantity),'pending') ON CONFLICT DO NOTHING; SELECT * INTO c FROM public.voucher_batch_chunks WHERE batch_id=b.id AND chunk_index=b.progress_cursor/100 FOR UPDATE; IF c.current_attempt_id IS NOT NULL THEN RAISE EXCEPTION 'voucher unavailable'; END IF; INSERT INTO public.voucher_batch_chunk_attempts(batch_id,chunk_index,attempt_number,claim_token,expected_count,status,lease_expires_at) VALUES(b.id,c.chunk_index,1,gen_random_uuid(),c.expected_count,'claimed',now()+interval '5 minutes') RETURNING * INTO a; UPDATE public.voucher_batch_chunks SET current_attempt_id=a.id,status='claimed' WHERE batch_id=b.id AND chunk_index=c.chunk_index; RETURN jsonb_build_object('done',false,'chunk_index',c.chunk_index,'attempt_id',a.id,'claim_token',a.claim_token,'expected_count',a.expected_count,'lease_expires_at',a.lease_expires_at,'mode','prepare'); END $$;
CREATE OR REPLACE FUNCTION public.prepare_voucher_admin_batch_chunk(p_batch_reference text,p_chunk_index bigint,p_attempt_id uuid,p_claim_token uuid,p_items jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE a public.voucher_batch_chunk_attempts%ROWTYPE;n integer; BEGIN SELECT a.* INTO a FROM public.voucher_batch_chunk_attempts a JOIN public.voucher_batches b ON b.id=a.batch_id WHERE b.batch_reference=p_batch_reference AND a.chunk_index=p_chunk_index AND a.id=p_attempt_id AND a.claim_token=p_claim_token FOR UPDATE; IF NOT FOUND OR a.status<>'claimed' OR a.lease_expires_at<=now() OR jsonb_typeof(p_items)<>'array' OR jsonb_array_length(p_items)<>a.expected_count THEN RAISE EXCEPTION 'voucher unavailable'; END IF; n:=jsonb_array_length(p_items); UPDATE public.voucher_batch_chunk_attempts SET stored_count=n,status='prepared',prepared_at=now(),last_safe_result_code='prepared' WHERE id=a.id; RETURN jsonb_build_object('prepared',true,'already_prepared',false,'attempt_id',a.id,'chunk_index',a.chunk_index,'expected_count',a.expected_count,'stored_count',n,'safe_result_code','prepared'); END $$;
CREATE OR REPLACE FUNCTION public.record_voucher_admin_chunk_delivery(p_batch_reference text,p_chunk_index bigint,p_attempt_id uuid,p_claim_token uuid,p_delivery_method text,p_telegram_message_id bigint,p_delivered_count integer) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ BEGIN IF p_delivery_method NOT IN ('message','document') OR p_telegram_message_id<=0 THEN RAISE EXCEPTION 'voucher unavailable'; END IF; UPDATE public.voucher_batch_chunk_attempts a SET delivered_count=p_delivered_count,status='delivered',delivery_method=p_delivery_method,telegram_message_id=p_telegram_message_id,delivered_at=now() FROM public.voucher_batches b WHERE b.id=a.batch_id AND b.batch_reference=p_batch_reference AND a.chunk_index=p_chunk_index AND a.id=p_attempt_id AND a.claim_token=p_claim_token AND a.status='prepared' AND a.stored_count=a.expected_count AND p_delivered_count=a.expected_count; IF NOT FOUND THEN RAISE EXCEPTION 'voucher unavailable'; END IF; RETURN jsonb_build_object('recorded',true); END $$;
CREATE OR REPLACE FUNCTION public.mark_voucher_admin_chunk_delivery_uncertain(p_batch_reference text,p_chunk_index bigint,p_attempt_id uuid,p_claim_token uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ BEGIN UPDATE public.voucher_batch_chunk_attempts a SET status='delivery_uncertain',uncertain_at=now() FROM public.voucher_batches b WHERE b.id=a.batch_id AND b.batch_reference=p_batch_reference AND a.chunk_index=p_chunk_index AND a.id=p_attempt_id AND a.claim_token=p_claim_token AND a.status='prepared'; RETURN jsonb_build_object('uncertain',true); END $$;
CREATE OR REPLACE FUNCTION public.finalize_voucher_admin_batch_chunk(p_batch_reference text,p_chunk_index bigint,p_attempt_id uuid,p_claim_token uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ BEGIN UPDATE public.voucher_batch_chunk_attempts a SET status='finalized',finalized_at=now() FROM public.voucher_batches b WHERE b.id=a.batch_id AND b.batch_reference=p_batch_reference AND a.chunk_index=p_chunk_index AND a.id=p_attempt_id AND a.claim_token=p_claim_token AND a.status='delivered' AND a.stored_count=a.expected_count AND a.delivered_count=a.expected_count; IF NOT FOUND THEN RAISE EXCEPTION 'voucher unavailable'; END IF; UPDATE public.subscription_vouchers SET active=true,delivery_pending=false WHERE attempt_id=p_attempt_id; RETURN jsonb_build_object('finalized',true); END $$;
CREATE OR REPLACE FUNCTION public.cancel_voucher_admin_batch_chunk(p_batch_reference text,p_chunk_index bigint,p_attempt_id uuid,p_claim_token uuid,p_reason text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ BEGIN UPDATE public.voucher_batch_chunk_attempts a SET status='cancelled',cancelled_at=now(),last_safe_result_code=left(p_reason,40) FROM public.voucher_batches b WHERE b.id=a.batch_id AND b.batch_reference=p_batch_reference AND a.chunk_index=p_chunk_index AND a.id=p_attempt_id AND a.claim_token=p_claim_token AND a.status IN ('claimed','prepared'); RETURN jsonb_build_object('cancelled',true); END $$;
REVOKE ALL ON FUNCTION public.claim_voucher_admin_batch_chunk(text),public.prepare_voucher_admin_batch_chunk(text,bigint,uuid,uuid,jsonb),public.record_voucher_admin_chunk_delivery(text,bigint,uuid,uuid,text,bigint,integer),public.mark_voucher_admin_chunk_delivery_uncertain(text,bigint,uuid,uuid),public.finalize_voucher_admin_batch_chunk(text,bigint,uuid,uuid),public.cancel_voucher_admin_batch_chunk(text,bigint,uuid,uuid,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.claim_voucher_admin_batch_chunk(text),public.prepare_voucher_admin_batch_chunk(text,bigint,uuid,uuid,jsonb),public.record_voucher_admin_chunk_delivery(text,bigint,uuid,uuid,text,bigint,integer),public.mark_voucher_admin_chunk_delivery_uncertain(text,bigint,uuid,uuid),public.finalize_voucher_admin_batch_chunk(text,bigint,uuid,uuid),public.cancel_voucher_admin_batch_chunk(text,bigint,uuid,uuid,text) TO service_role;
COMMIT;
